    \[ D_f = \{x \in \mathbb{R} \mid x &lt; 1 \text{ atau } x &gt; 2\} \]
    atau dalam notasi interval:
    \[ D_f = (-\infty, 1) \cup (2, \infty) \]

problems.solution_raw:
\textbf{Langkah-langkah sketsa grafik:}
    \begin{enumerate}
        \item \textbf{Arah parabola:} Karena koefisien $x^2$ bernilai negatif ($a = -1$), grafik terbuka ke bawah.
        \item \textbf{Titik potong sumbu-$y$ ($x=0$):} $f(0) = -3 \implies (0, -3)$.
        \item \textbf{Titik potong sumbu-$x$ ($f(x)=0$):}
        \[ -x^2 + 4x - 3 = 0 \implies x^2 - 4x + 3 = 0 \implies (x-1)(x-3) = 0 \]
        Diperoleh titik potong di $x=1$ dan $x=3$, yaitu $(1, 0)$ dan $(3, 0)$.
        \item \textbf{Titik puncak $(x_p, y_p)$:}
        \[ x_p = -\frac{b}{2a} = -\frac{4}{2(-1)} = 2 \]
        \[ y_p = f(2) = -(2)^2 + 4(2) - 3 = 1 \]
        Titik puncak berada di $(2, 1)$.
    \end{enumerate}

