Grafik fungsi $y = 2\cos(2x)$:
    \begin{itemize}
        \item \textbf{Amplitudo:} $A = 2$. Nilai maksimum adalah $2$ dan minimum adalah $-2$.
        \item \textbf{Periode:} $T = \dfrac{2\pi}{k} = \dfrac{2\pi}{2} = \pi$. Berarti dalam interval $[0, \pi]$ terdapat tepat satu gelombang cosinus penuh.
        \item \textbf{Titik-titik kunci:}
        \begin{itemize}
            \item $x = 0 \implies y = 2\cos(0) = 2$ \quad (puncak atas)
            \item $x = \dfrac{\pi}{4} \implies y = 2\cos\!\left(\dfrac{\pi}{2}\right) = 0$ \quad (potong sumbu-$x$)
            \item $x = \dfrac{\pi}{2} \implies y = 2\cos(\pi) = -2$ \quad (puncak bawah)
            \item $x = \dfrac{3\pi}{4} \implies y = 2\cos\!\left(\dfrac{3\pi}{2}\right) = 0$ \quad (potong sumbu-$x$)
            \item $x = \pi \implies y = 2\cos(2\pi) = 2$ \quad (puncak atas)
        \end{itemize}
    \end{itemize}

