Gunakan identitas trigonometri $1 - \cos(x) = 2\sin^2\left(\frac{x}{2}\right)$:
    \begin{align*}
        \limit{x}{0} \frac{2\sin^2(x/2)}{x^2} &= 2 \limit{x}{0} \left( \frac{\sin(x/2)}{x} \right)^2 \\
        &= 2 \limit{x}{0} \left( \frac{\sin(x/2)}{2 \cdot (x/2)} \right)^2 \\
        &= 2 \left( \frac{1}{2} \cdot 1 \right)^2 = 2 \cdot \frac{1}{4} = \frac{1}{2}
    \end{align*}

problems.solution_raw:
Ingat definisi nilai mutlak $|x| = x$ jika $x \geq 0$ dan $|x| = -x$ jika $x < 0$, serta definisi fungsi floor $\lfloor x \rfloor$ yaitu bilangan bulat terbesar yang kurang dari atau sama dengan $x$.
    \begin{itemize}
        \item \textbf{Limit Kiri ($x \to 0^-$):} Untuk $-1 < x < 0$, kita memiliki $|x| = -x$ dan $\lfloor x \rfloor = -1$.
        \[ \limit{x}{0^-} \frac{|x|\lfloor x \rfloor}{x} = \limit{x}{0^-} \frac{-x \cdot (-1)}{x} = \limit{x}{0^-} \frac{x}{x} = 1 \]
        \item \textbf{Limit Kanan ($x \to 0^+$):} Untuk $0 < x < 1$, kita memiliki $|x| = x$ dan $\lfloor x \rfloor = 0$.
        \[ \limit{x}{0^+} \frac{|x|\lfloor x \rfloor}{x} = \limit{x}{0^+} \frac{x \cdot 0}{x} = 0 \]
    \end{itemize}
    Karena $\limit{x}{0^-} f(x) \neq \limit{x}{0^+} f(x)$, maka $\limit{x}{0} \frac{|x|\lfloor x \rfloor}{x}$ \textbf{tidak ada.}

problems.problem_raw:
\textbf{(12 Poin)} Hitunglah nilai limit berikut. Jika limit tidak ada, jelaskan alasannya melalui analisis limit kiri dan limit kanan!
    \begin{enumerate}
        \item \textbf{(4 Poin)} $\limit{x}{0} \frac{1-\cos(4x)}{x\sin(2x)}$
        \item \textbf{(4 Poin)} $\limit{x}{1} \frac{x^2-1}{|x-1|}$
        \item \textbf{(4 Poin)} $\limit{x}{\infty} (\sqrt{4x^2+3x-1}-2x)$
    \end{enumerate}

problems.solution_raw:
\begin{enumerate}
        \item Menggunakan identitas trigonometri $\cos(4x) = 1 - 2\sin^2(2x)$, diperoleh $1 - \cos(4x) = 2\sin^2(2x)$. 
        Substitusikan ke dalam limit:
        \[ \limit{x}{0} \frac{1-\cos(4x)}{x\sin(2x)} = \limit{x}{0} \frac{2\sin^2(2x)}{x\sin(2x)} \]
        Karena $x \to 0$ ($x \neq 0$), maka $\sin(2x) \neq 0$, sehingga kita dapat membagi pembilang dan penyebut dengan $\sin(2x)$:
        \[ = \limit{x}{0} \frac{2\sin(2x)}{x} = \limit{x}{0} \left( 4 \cdot \frac{\sin(2x)}{2x} \right) = 4 \cdot 1 = 4 \]

        \item Evaluasi limit di $x = 1$ melalui limit sepihak:
        \begin{itemize}
            \item \textbf{Limit Kanan ($x \to 1^+$):} Untuk $x > 1$, berlaku $|x-1| = x-1$.
            \[ \limit{x}{1^+} \frac{x^2-1}{|x-1|} = \limit{x}{1^+} \frac{(x-1)(x+1)}{x-1} = \limit{x}{1^+} (x+1) = 1+1 = 2 \]
            \item \textbf{Limit Kiri ($x \to 1^-$):} Untuk $x < 1$, berlaku $|x-1| = -(x-1)$.
            \[ \limit{x}{1^-} \frac{x^2-1}{|x-1|} = \limit{x}{1^-} \frac{(x-1)(x+1)}{-(x-1)} = \limit{x}{1^-} -(x+1) = -(1+1) = -2 \]
        \end{itemize}
        Karena nilai limit kiri dan limit kanan tidak sama ($\limit{x}{1^-} f(x) = -2 \neq 2 = \limit{x}{1^+} f(x)$), maka \textbf{limit tersebut tidak ada}.

        \item Kalikan dengan bentuk sekawannya:
        \begin{align*}
            \limit{x}{\infty} \left( \sqrt{4x^2+3x-1}-2x \right) &= \limit{x}{\infty} \frac{\left( \sqrt{4x^2+3x-1}-2x \right)\left( \sqrt{4x^2+3x-1}+2x \right)}{\sqrt{4x^2+3x-1}+2x} \\
            &= \limit{x}{\infty} \frac{(4x^2+3x-1) - 4x^2}{\sqrt{4x^2+3x-1}+2x} \\
            &= \limit{x}{\infty} \frac{3x-1}{\sqrt{x^2\left( 4 + \frac{3}{x} - \frac{1}{x^2} \right)} + 2x}
        \end{align*}
        Karena $x \to \infty$, maka $\sqrt{x^2} = |x| = x$. Bagi pembilang dan penyebut dengan $x$:
        \[ = \limit{x}{\infty} \frac{3 - \frac{1}{x}}{\sqrt{4 + \frac{3}{x} - \frac{1}{x^2}} + 2} = \frac{3 - 0}{\sqrt{4+0-0}+2} = \frac{3}{2+2} = \frac{3}{4} \]
    \end{enumerate}

Faktorkan pembilang dan penyebut fungsi $g(x)$:
    \[ g(x) = \frac{(x-4)(x+1)}{(x-4)(x+4)} \]

    \begin{enumerate}
        \item \textbf{Domain Fungsi $g(x)$:}
        Fungsi rasional terdefinisi jika dan hanya jika penyebutnya tidak sama dengan nol:
        \[ x^2-16 \neq 0 \implies (x-4)(x+4) \neq 0 \implies x \neq 4 \text{ dan } x \neq -4 \]
        Jadi, domain dari fungsi $g(x)$ adalah:
        \[ D_g = \{x \in \R \mid x \neq \pm 4\} \quad \text{atau} \quad (-\infty, -4) \cup (-4, 4) \cup (4, \infty) \]

        \item \textbf{Asimtot Fungsi $g(x)$:}
        \begin{itemize}
            \item \textbf{Asimtot Datar:}
            Hitung limit fungsi ketika $x \to \pm\infty$:
            \[ \limit{x}{\pm\infty} g(x) = \limit{x}{\pm\infty} \frac{x^2-3x-4}{x^2-16} = \limit{x}{\pm\infty} \frac{1 - 3/x - 4/x^2}{1 - 16/x^2} = 1 \]
            Karena limitnya menuju $1$, persamaan asimtot datarnya adalah \textbf{$y = 1$}.

            \item \textbf{Asimtot Tegak:}
            Kandidat asimtot tegak adalah $x = 4$ dan $x = -4$ (pembuat nol penyebut).
            \begin{itemize}
                \item Untuk $x = 4$:
                \[ \limit{x}{4} g(x) = \limit{x}{4} \frac{(x-4)(x+1)}{(x-4)(x+4)} = \limit{x}{4} \frac{x+1}{x+4} = \frac{5}{8} \]
                Karena limitnya berhingga, $x = 4$ \textbf{bukan asimtot tegak} (terdapat \textit{removable discontinuity} / lubang).
                \item Untuk $x = -4$:
                Evaluasi limit sepihak:
                \[ \limit{x}{-4^+} g(x) = \limit{x}{-4^+} \frac{x+1}{x+4} = -\infty \]
                (pembilang mendekati $-3$, sedangkan penyebut mendekati $0$ dari arah positif).
                Karena salah satu limit sepihak bernilai $\pm\infty$, maka \textbf{$x = -4$ adalah asimtot tegak}.
            \end{itemize}
        \end{itemize}

        \item \textbf{Perpotongan dengan Asimtot Datar ($y = 1$):}
        Selesaikan persamaan $g(x) = 1$ pada domain $D_g$:
        \[ \frac{x^2-3x-4}{x^2-16} = 1 \implies x^2-3x-4 = x^2-16 \implies -3x = -12 \implies x = 4 \]
        Namun, nilai $x = 4$ tidak berada di dalam domain $D_g$. Oleh karena itu, kurva fungsi $g(x)$ \textbf{tidak memotong} asimtot datarnya.
    \end{enumerate}

Definisi turunan pertama menggunakan limit:
    \[ f'(x) = \limit{h}{0} \frac{f(x+h) - f(x)}{h} \]
    Substitusikan $f(x) = \frac{1}{\sqrt{x+2}}$:
    \begin{align*}
        f'(x) &= \limit{h}{0} \frac{\frac{1}{\sqrt{x+h+2}} - \frac{1}{\sqrt{x+2}}}{h} \\
        &= \limit{h}{0} \frac{\frac{\sqrt{x+2} - \sqrt{x+h+2}}{\sqrt{x+h+2}\sqrt{x+2}}}{h} \\
        &= \limit{h}{0} \frac{\sqrt{x+2} - \sqrt{x+h+2}}{h\sqrt{x+h+2}\sqrt{x+2}}
    \end{align*}
    Kalikan pembilang dan penyebut dengan bentuk sekawan $(\sqrt{x+2} + \sqrt{x+h+2})$:
    \begin{align*}
        f'(x) &= \limit{h}{0} \frac{(\sqrt{x+2} - \sqrt{x+h+2})(\sqrt{x+2} + \sqrt{x+h+2})}{h\sqrt{x+h+2}\sqrt{x+2}(\sqrt{x+2} + \sqrt{x+h+2})} \\
        &= \limit{h}{0} \frac{(x+2) - (x+h+2)}{h\sqrt{x+h+2}\sqrt{x+2}(\sqrt{x+2} + \sqrt{x+h+2})} \\
        &= \limit{h}{0} \frac{-h}{h\sqrt{x+h+2}\sqrt{x+2}(\sqrt{x+2} + \sqrt{x+h+2})}
    \end{align*}
    Karena $h \to 0$ ($h \neq 0$), bagilah pembilang dan penyebut dengan $h$:
    \[ = \limit{h}{0} \frac{-1}{\sqrt{x+h+2}\sqrt{x+2}(\sqrt{x+2} + \sqrt{x+h+2})} \]
    Evaluasi limit dengan mensubstitusi $h = 0$:
    \[ = \frac{-1}{\sqrt{x+2}\sqrt{x+2}(\sqrt{x+2} + \sqrt{x+2})} = \frac{-1}{(x+2)(2\sqrt{x+2})} = -\frac{1}{2(x+2)^{3/2}} \]
    Jadi, didapatkan turunan pertamanya adalah $f'(x) = -\frac{1}{2(x+2)^{3/2}}$.

problems.solution_html:
Definisi turunan pertama menggunakan limit:
    \[ f'(x) = \limit{h}{0} \frac{f(x+h) - f(x)}{h} \]
    Substitusikan $f(x) = \frac{1}{\sqrt{x+2}}$:
    \begin{align*}
        f'(x) &= \limit{h}{0} \frac{\frac{1}{\sqrt{x+h+2}} - \frac{1}{\sqrt{x+2}}}{h} \\
        &= \limit{h}{0} \frac{\frac{\sqrt{x+2} - \sqrt{x+h+2}}{\sqrt{x+h+2}\sqrt{x+2}}}{h} \\
        &= \limit{h}{0} \frac{\sqrt{x+2} - \sqrt{x+h+2}}{h\sqrt{x+h+2}\sqrt{x+2}}
    \end{align*}
    Kalikan pembilang dan penyebut dengan bentuk sekawan $(\sqrt{x+2} + \sqrt{x+h+2})$:
    \begin{align*}
        f'(x) &= \limit{h}{0} \frac{(\sqrt{x+2} - \sqrt{x+h+2})(\sqrt{x+2} + \sqrt{x+h+2})}{h\sqrt{x+h+2}\sqrt{x+2}(\sqrt{x+2} + \sqrt{x+h+2})} \\
        &= \limit{h}{0} \frac{(x+2) - (x+h+2)}{h\sqrt{x+h+2}\sqrt{x+2}(\sqrt{x+2} + \sqrt{x+h+2})} \\
        &= \limit{h}{0} \frac{-h}{h\sqrt{x+h+2}\sqrt{x+2}(\sqrt{x+2} + \sqrt{x+h+2})}
    \end{align*}
    Karena $h \to 0$ ($h \neq 0$), bagilah pembilang dan penyebut dengan $h$:
    \[ = \limit{h}{0} \frac{-1}{\sqrt{x+h+2}\sqrt{x+2}(\sqrt{x+2} + \sqrt{x+h+2})} \]
    Evaluasi limit dengan mensubstitusi $h = 0$:
    \[ = \frac{-1}{\sqrt{x+2}\sqrt{x+2}(\sqrt{x+2} + \sqrt{x+2})} = \frac{-1}{(x+2)(2\sqrt{x+2})} = -\frac{1}{2(x+2)^{3/2}} \]
    Jadi, didapatkan turunan pertamanya adalah $f'(x) = -\frac{1}{2(x+2)^{3/2}}$.

problems.problem_raw:
\textbf{(12 Poin)} Diketahui fungsi sebagai berikut.
    \[ h(x) = \begin{cases} 
    cx^2+d, & \text{jika } x \leq 2 \\ 
    2x^3-cx, & \text{jika } x > 2
    \end{cases} \]
    \begin{enumerate}
        \item \textbf{(6 Poin)} Tentukan nilai $c$ dan $d$ sehingga fungsi $h(x)$ \textit{differentiable} di $x=2$.
        \item \textbf{(6 Poin)} Berdasarkan teorema \href{https://ocw.mit.edu/courses/18-01sc-single-variable-calculus-fall-2010/80d39e825d96c3c4930171cb8c6e96fb_MIT18_01SCF10_Ses5e.pdf}{\texttt{Differentiability implies Continuity}}, jelaskan dengan kata-kata Anda sendiri mengapa mencari nilai $c$ dan $d$ pada subsoal (a) mengharuskan Anda menetapkan bahwa $h(x)$ kontinu di $x=2$ terlebih dahulu.
    \end{enumerate}

problems.solution_raw:
\begin{enumerate}
        \item Agar fungsi $h(x)$ dapat diturunkan (\textit{differentiable}) di $x = 2$, harus dipenuhi dua syarat:
        \begin{itemize}
            \item \textbf{Syarat 1: Fungsi Kontinu di $x = 2$}
            Kekontinuan di $x = 2$ mensyaratkan limit kiri sama dengan limit kanan:
            \[ \limit{x}{2^-} h(x) = \limit{x}{2^+} h(x) \implies c(2)^2 + d = 2(2)^3 - c(2) \implies 4c + d = 16 - 2c \]
            \[ 6c + d = 16 \quad \text{--- (Persamaan 1)} \]

            \item \textbf{Syarat 2: Turunan Kiri sama dengan Turunan Kanan di $x = 2$}
            Turunan kiri dan kanan harus bernilai sama\footnote{Notasi $h'_{-}(a)$ dan $h'_{+}(a)$ masing-masing menyatakan turunan kiri dan turunan kanan dari fungsi $h$ di $x=a$.}:
            \[ h'_{-}(2) = h'_{+}(2) \]
            Untuk $x < 2$, turunan dari $h(x) = cx^2+d$ adalah $2cx$, sehingga $h'_{-}(2) = 2c(2) = 4c$. \\
            Untuk $x > 2$, turunan dari $h(x) = 2x^3-cx$ adalah $6x^2-c$, sehingga $h'_{+}(2) = 6(2)^2 - c = 24 - c$.
            \[ 4c = 24 - c \implies 5c = 24 \implies c = \frac{24}{5} = 4.8 \]
            Substitusikan nilai $c = 4.8$ ke dalam Persamaan 1 untuk mencari $d$:
            \[ 6(4.8) + d = 16 \implies 28.8 + d = 16 \implies d = 16 - 28.8 = -12.8 = -\frac{64}{5} \]
        \end{itemize}
        Jadi, nilai $c$ dan $d$ yang memenuhi adalah $c = \frac{24}{5}$ (atau $4.8$) dan $d = -\frac{64}{5}$ (atau $-12.8$).

        \item Teorema \textit{Differentiability implies Continuity} menyatakan bahwa jika suatu fungsi dapat diturunkan di suatu titik, maka ia pasti kontinu di titik tersebut. Artinya, kekontinuan adalah \textbf{syarat perlu} (tetapi \textbf{bukan syarat cukup}) agar suatu fungsi memiliki turunan. Perlu dicatat bahwa kebalikan dari teorema ini tidak selalu berlaku; fungsi yang kontinu di suatu titik tidak menjamin fungsi tersebut dapat diturunkan di titik tersebut (contohnya fungsi $f(x) = |x|$ kontinu di $x=0$ tetapi tidak memiliki turunan di sana). Oleh karena itu, jika fungsi $h(x)$ tidak kontinu di $x=2$, grafiknya akan terputus (memiliki lompatan) dan tidak mungkin mendefinisikan kemiringan garis singgung yang tunggal di titik tersebut. Hal ini mengharuskan kita untuk menetapkan syarat kekontinuan (Persamaan 1) terlebih dahulu sebelum menyamakan turunan sepihaknya (Persamaan 2) untuk memastikan keberadaan turunan yang valid di $x = 2$.
    \end{enumerate}

problems.problem_raw:
\textbf{(10 Poin)} Tentukan turunan pertama dari fungsi-fungsi berikut. Perhatikan bahwa Anda tidak perlu menyederhanakan hasil akhirnya.
    \begin{enumerate}
        \item \textbf{(5 Poin)} $y=e^{-3x}x^4\sin(5x)$
        \item \textbf{(5 Poin)} $y=\left( \frac{\ln(x^2+1)}{\cos(3x)}\right)^4$
    \end{enumerate}

\textbf{(10 Poin)} Diberikan fungsi $f(x)=\sec(e^{\sqrt{x}})$. Tentukan:
    \begin{enumerate}
        \item \textbf{(5 Poin)} Ekspresi dari $f'(x)$.
        \item \textbf{(5 Poin)} Tentukan persamaan garis singgung dari kurva $f(x)$ pada saat $x = \ln^2(\frac{\pi}{3})$.
    \end{enumerate}

problems.solution_raw:
\begin{enumerate}
        \item Gunakan aturan rantai berulang. Ingat bahwa $\frac{\mathrm{d}}{\mathrm{d}x} \sec(u) = \sec(u)\tan(u) \cdot u'$:
        \[ f'(x) = \sec(e^{\sqrt{x}})\tan(e^{\sqrt{x}}) \cdot \frac{\mathrm{d}}{\mathrm{d}x}\left( e^{\sqrt{x}} \right) \]
        Karena $\frac{\mathrm{d}}{\mathrm{d}x}\left( e^{\sqrt{x}} \right) = e^{\sqrt{x}} \cdot \frac{1}{2\sqrt{x}}$, maka:
        \[ f'(x) = \frac{e^{\sqrt{x}}\sec(e^{\sqrt{x}})\tan(e^{\sqrt{x}})}{2\sqrt{x}} \]

        \item Tentukan persamaan garis singgung pada $x_0 = \ln^2\left(\frac{\pi}{3}\right)$:
        \begin{itemize}
            \item \textbf{Titik Singgung ($y_0$):}
            Karena $\frac{\pi}{3} > 1$, maka $\ln(\frac{\pi}{3}) > 0$, sehingga $\sqrt{x_0} = \ln(\frac{\pi}{3})$. \\
            Diperoleh $e^{\sqrt{x_0}} = e^{\ln(\pi/3)} = \frac{\pi}{3}$.
            \[ y_0 = f(x_0) = \sec\left(\frac{\pi}{3}\right) = \frac{1}{\cos(\pi/3)} = \frac{1}{1/2} = 2 \]
            Titik singgungnya adalah $\left(\ln^2\left(\frac{\pi}{3}\right), 2\right)$.

            \item \textbf{Gradien Garis Singgung ($m$):}
            Evaluasi $f'(x_0)$ dengan mensubstitusi $x_0 = \ln^2\left(\frac{\pi}{3}\right)$:
            \[ m = f'\left(\ln^2\left(\frac{\pi}{3}\right)\right) = \frac{\left(\frac{\pi}{3}\right)\sec\left(\frac{\pi}{3}\right)\tan\left(\frac{\pi}{3}\right)}{2\ln\left(\frac{\pi}{3}\right)} \]
            Gunakan $\sec(\frac{\pi}{3}) = 2$ dan $\tan(\frac{\pi}{3}) = \sqrt{3}$:
            \[ m = \frac{\frac{\pi}{3} \cdot 2 \cdot \sqrt{3}}{2\ln\left(\frac{\pi}{3}\right)} = \frac{\pi\sqrt{3}}{3\ln\left(\frac{\pi}{3}\right)} \]

            \item \textbf{Persamaan Garis Singgung:}
            Menggunakan rumus garis singgung $y - y_0 = m(x - x_0)$:
            \[ y - 2 = \frac{\pi\sqrt{3}}{3\ln\left(\frac{\pi}{3}\right)} \left( x - \ln^2\left(\frac{\pi}{3}\right) \right) \]
        \end{itemize}
    \end{enumerate}

problems.problem_raw:
\textbf{(9 Poin)} Diberikan fungsi $f(x)=|x^2-9|$. Jawab pertanyaan berikut.
    \begin{enumerate}
        \item \textbf{(6 Poin)} Tanpa menggunakan aturan turunan baku, gunakan definisi turunan sepihak (limit kiri dan limit kanan) untuk membuktikan bahwa fungsi $f(x)$ tidak dapat diturunkan di $x=3$.
        \item \textbf{(3 Poin)} Apakah $f(x)$ kontinu di $x=3$? Jelaskan kesimpulan Anda mengaitkan poin (a) dengan grafik fungsi tersebut di sekitar $x=3$. 
    \end{enumerate}

problems.solution_raw:
Fungsi nilai mutlak $f(x) = |x^2-9|$ dapat dipecah di sekitar $x = 3$ menjadi:
    \[ f(x) = \begin{cases} x^2-9, & \text{jika } x \geq 3 \\ -(x^2-9) = 9-x^2, & \text{jika } -3 < x < 3 \end{cases} \]
    Serta nilai fungsinya adalah $f(3) = 0$.

    \begin{enumerate}
        \item \textbf{Turunan Sepihak di $x = 3$}:
        \begin{itemize}
            \item \textbf{Turunan Kanan ($f'_{+}(3)$):}
            \[ f'_{+}(3) = \limit{h}{0^+} \frac{f(3+h)-f(3)}{h} \]
            Karena $h \to 0^+$, maka $3+h > 3$, gunakan ekspresi $f(x) = x^2-9$:
            \begin{align*}
                f'_{+}(3) &= \limit{h}{0^+} \frac{((3+h)^2-9) - 0}{h} \\
                &= \limit{h}{0^+} \frac{9+6h+h^2-9}{h} \\
                &= \limit{h}{0^+} (6+h) = 6
            \end{align*}

            \item \textbf{Turunan Kiri ($f'_{-}(3)$):}
            \[ f'_{-}(3) = \limit{h}{0^-} \frac{f(3+h)-f(3)}{h} \]
            Karena $h \to 0^-$, maka $3+h < 3$, gunakan ekspresi $f(x) = 9-x^2$:
            \begin{align*}
                f'_{-}(3) &= \limit{h}{0^-} \frac{(9-(3+h)^2) - 0}{h} \\
                &= \limit{h}{0^-} \frac{9-(9+6h+h^2)}{h} \\
                &= \limit{h}{0^-} \frac{-6h-h^2}{h} = -6
            \end{align*}
        \end{itemize}
        Karena turunan kiri tidak sama dengan turunan kanan ($f'_{-}(3) = -6 \neq 6 = f'_{+}(3)$), limit definisi turunan di $x = 3$ tidak ada. Terbukti bahwa fungsi $f(x)$ \textbf{tidak dapat diturunkan} di $x=3$.

        \item \textbf{Kekontinuan dan Interpretasi Grafis:}
        Evaluasi limit fungsi di $x = 3$:
        \[ \limit{x}{3^+} f(x) = \limit{x}{3^+} (x^2-9) = 0 \]
        \[ \limit{x}{3^-} f(x) = \limit{x}{3^-} (9-x^2) = 0 \]
        Karena $\limit{x}{3} f(x) = f(3) = 0$, fungsi $f(x)$ \textbf{kontinu} di $x = 3$. \\
        \textbf{Hubungan dengan grafik:} Meskipun kontinu (grafik tidak terputus), fungsi tidak dapat diturunkan di $x = 3$ karena grafiknya memiliki \textbf{sudut tajam (corner)} pada titik $(3,0)$. Pada sudut tajam tersebut, perubahan kemiringan terjadi secara drastis dari $-6$ menjadi $6$, sehingga tidak ada garis singgung unik yang dapat didefinisikan.

        \begin{center}
        \begin{tikzpicture}
            \begin{axis}[
                axis lines = center,
                xlabel = {$x$},
                ylabel = {$y$},
                xlabel style = {right},
                ylabel style = {above},
                xmin = -5.5, xmax = 5.5,
                ymin = -0.8, ymax = 10.5,
                xtick = {-5,-4,-3,-2,-1,1,2,3,4,5},
                ytick = {2,4,6,8,9,10},
                tick label style = {font=\small},
                width  = 10cm,
                height = 7cm,
                grid = both,
                grid style = {line width=0.3pt, draw=gray!25},
                clip = false,
            ]
                % Bagian kiri: f(x) = x^2 - 9 untuk x <= -3
                \addplot[blue, very thick, domain=-5:-3, samples=80] {x^2 - 9};

                % Bagian tengah: f(x) = 9 - x^2 untuk -3 <= x <= 3
                \addplot[red, very thick, domain=-3:3, samples=100] {9 - x^2};

                % Bagian kanan: f(x) = x^2 - 9 untuk x >= 3
                \addplot[blue, very thick, domain=3:5, samples=80] {x^2 - 9};

                % Titik sudut tajam (corner) di x = -3 dan x = 3
                \addplot[only marks, mark=*, mark size=3pt, black]
                    coordinates {(-3,0) (3,0)};

                % Titik puncak di x = 0
                \addplot[only marks, mark=*, mark size=3pt, black]
                    coordinates {(0,9)};

                % Label bagian kurva
