problems.problem_raw:
Diberikan fungsi transenden $f(x) = \ln\left( x + \sqrt{x^2 + 1} \right)$ untuk seluruh $x \in \R$.
    \begin{enumerate}
        \item Tentukan turunan pertama $f'(x)$ dan nyatakan dalam bentuk yang paling sederhana.
        \item Definisikan fungsi $g(x) = f(x) + f(-x)$. Tunjukkan dengan menggunakan konsep turunan bahwa $g'(x) = 0$ untuk setiap $x \in \R$, lalu simpulkan karakteristik dari fungsi $g(x)$.
        \item Verifikasi secara aljabar hasil yang diperoleh pada bagian (b) dengan cara menyederhanakan bentuk $f(x) + f(-x)$ secara langsung tanpa menggunakan turunan.
    \end{enumerate}

Tinjau kurva yang didefinisikan oleh persamaan parametrik berikut:
    \[ x(t) = \cos(2t), \quad y(t) = \sin(3t) \]
    \begin{enumerate}
    \item Tentukan $\frac{\mathrm{d}^2y}{\mathrm{d}x^2}$
    \item Hitung nilai $\frac{\mathrm{d}^2y}{\mathrm{d}x^2}$ dengan parameter $t = \frac{\pi}{6}$
    \end{enumerate}

problems.solution_raw:
\begin{enumerate}
        \item \textbf{Tentukan $\frac{\mathrm{d}^2y}{\mathrm{d}x^2}$:}

            Tentukan turunan pertama terhadap t:
            \[\df{x}{t} = -2 \sin \left(2t\right)\]
            \[\df{y}{t} = 3 \cos \left(3t\right)\]

            Tentukan $\left(\df{y}{x}\right)$:
            \[\df{y}{x} = \frac{\df{y}{t}}{\df{x}{t}} = \frac{3 \cos \left(3t\right)}{-2 \sin \left(2t\right)}\]

            Turunkan $\df{y}{x}$ terhadap $t$:

            Pemisalan $u$ dan $v$:
            \begin{itemize}
                \item $\frac{3 \cos \left(3t\right)}{-2 \sin \left(2t\right)} = \frac{u}{v}$  
                \item $u = 3 \cos \left(3t\right) \implies \df{u}{t} = 3 \cdot -3 \sin \left(3t\right) = -9 \sin \left(3t\right)$
                \item $v = -2 \sin \left(2t\right) \implies \df{v}{t} = -2 \cdot 2 \cos \left(2t\right) = -4 \cos \left(2t\right)$  
            \end{itemize}

            Selesaikan turunan $\df{y}{x}$ terhadap $t$:
            \[\df{}{t} \left(\df{y}{x}\right) = \frac{\left(-9 \sin \left(3t\right)\right) \left(-2 \sin \left(2t\right)\right) - \left(3 \cos \left(3t\right)\right) \left(-4 \cos \left(2t\right)\right)}
                                                    {\left(-2 \sin \left(2t\right)\right)^2}\]
                                            \[= \frac{18 \sin \left(3t\right) \sin \left(2t\right) + 12 \cos \left(3t\right) \cos \left(2t\right)}
                                                    {4 {\sin}^2 \left(2t\right)}\]

            Tentukan turunan kedua $\frac{\mathrm{d}^2y}{\mathrm{d}x^2}$:
            \[\frac{\mathrm{d}^2y}{\mathrm{d}x^2} = \frac{\df{}{t} \left(\df{y}{x}\right)}{\df{x}{t}} = \df{}{t} \left(\df{y}{x}\right) \cdot \frac{1}{\df{x}{t}}\]
            \[= \frac{18 \sin \left(3t\right) \sin \left(2t\right) + 12 \cos \left(3t\right) \cos \left(2t\right)}
                                                    {4 {\sin}^2 \left(2t\right)}
                                                    \cdot \frac{1}{-2 \sin \left(2t\right)}\]

            \[= \frac{18 \sin \left(3t\right) \sin \left(2t\right) + 12 \cos \left(3t\right) \cos \left(2t\right)}
                                                    {-8 {\sin}^3 \left(2t\right)}\]

        \item \textbf{Hitung nilai $\frac{\mathrm{d}^2y}{\mathrm{d}x^2}$ dengan parameter $t = \frac{\pi}{6}$}
            Sudut yang dibentuk dari $t = \frac{\pi}{6}$:
            \begin{itemize}
                \item $2t = 2 \cdot \frac{\pi}{6} = \frac{\pi}{3} \left(60^{\circ}\right) $
                \item $3t = 3 \cdot \frac{\pi}{6} = \frac{\pi}{2} \left(90^{\circ}\right) $
            \end{itemize}  

            Nilai-nilai trigonometri:
            \begin{itemize}
                \item $\sin \left(\frac{\pi}{3}\right) = \frac{\sqrt{3}}{2}$
                \item $\cos \left(\frac{\pi}{3}\right) = \frac{1}{2}$
                \item $\sin \left(\frac{\pi}{2}\right) = 1$
                \item $\cos \left(\frac{\pi}{2}\right) = 0$
            \end{itemize}

            Substitusi nilai-nilai trigonometri tersebut:
            $$\left. \frac{d^2y}{dx^2} \right|_{t=\frac{\pi}{6}} 
               = \frac{18 \left(1\right) \left(\frac{\sqrt{3}}{2}\right) + 12 \left(0\right) \left(\frac{1}{2}\right)} {-8 \left(\frac{\sqrt{3}}{2}\right)^3}$$
            $$ = \frac{9 \sqrt{3} + 0} {-8 \left(\frac{3\sqrt{3}}{8}\right)}$$
            $$ = \frac{9 \sqrt{3}} {-3\sqrt{3}}$$
            $$ = -3 $$

    \end{enumerate}

Untuk menyelesaikan integral fungsi bernilai mutlak, pertama-tama tentukan titik pembuat nol dari fungsi di dalam nilai mutlak pada interval integrasi $[0, \pi]$:
    \[ 
    \cos x + \frac{1}{2} = 0 \implies \cos x = -\frac{1}{2} 
    \]
    Pada interval $[0, \pi]$, nilai $x$ yang memenuhi adalah:
    \[ 
    x = \frac{2\pi}{3} 
    \]
    Selidiki tanda dari ekspresi $\cos x + \frac{1}{2}$ pada kedua sub-interval:
    \begin{itemize}
        \item Untuk $0 \leq x < \frac{2\pi}{3}$: nilai $\cos x > -\frac{1}{2}$, sehingga $\cos x + \frac{1}{2} > 0$. Maka:
        \[ 
        \left| \cos x + \frac{1}{2} \right| = \cos x + \frac{1}{2} 
        \]
        \item Untuk $\frac{2\pi}{3} < x \leq \pi$: nilai $\cos x < -\frac{1}{2}$, sehingga $\cos x + \frac{1}{2} < 0$. Maka:
        \[ 
        \left| \cos x + \frac{1}{2} \right| = -\left(\cos x + \frac{1}{2}\right) = -\cos x - \frac{1}{2} 
        \]
    \end{itemize}
    Pecah integral tentu menjadi dua bagian berdasarkan batas tersebut:
    \[ 
    I = \int_0^{\frac{2\pi}{3}} \left( \cos x + \frac{1}{2} \right) \dx + \int_{\frac{2\pi}{3}}^{\pi} \left( -\cos x - \frac{1}{2} \right) \dx 
    \]
    Evaluasi integral masing-masing bagian:
    \begin{enumerate}
        \item Bagian pertama:
        \begin{align*}
            \int_0^{\frac{2\pi}{3}} \left( \cos x + \frac{1}{2} \right) \dx &= \left[ \sin x + \frac{1}{2}x \right]_0^{\frac{2\pi}{3}} \\
            &= \left( \sin\left(\frac{2\pi}{3}\right) + \frac{1}{2}\left(\frac{2\pi}{3}\right) \right) - (0) \\
            &= \frac{\sqrt{3}}{2} + \frac{\pi}{3} 
        \end{align*}
        \item Bagian kedua:
        \begin{align*}
            \int_{\frac{2\pi}{3}}^{\pi} \left( -\cos x - \frac{1}{2} \right) \dx &= \left[ -\sin x - \frac{1}{2}x \right]_{\frac{2\pi}{3}}^{\pi} \\
            &= \left( -\sin(\pi) - \frac{\pi}{2} \right) - \left( -\sin\left(\frac{2\pi}{3}\right) - \frac{1}{2}\left(\frac{2\pi}{3}\right) \right) \\
            &= \left( 0 - \frac{\pi}{2} \right) - \left( -\frac{\sqrt{3}}{2} - \frac{\pi}{3} \right) \\
            &= -\frac{\pi}{2} + \frac{\sqrt{3}}{2} + \frac{\pi}{3} = \frac{\sqrt{3}}{2} - \frac{\pi}{6} 
        \end{align*}
    \end{enumerate}
    Jumlahkan kedua bagian tersebut:
    \begin{align*}
        I &= \left( \frac{\sqrt{3}}{2} + \frac{\pi}{3} \right) + \left( \frac{\sqrt{3}}{2} - \frac{\pi}{6} \right) \\
        &= 2\left(\frac{\sqrt{3}}{2}\right) + \left(\frac{2\pi - \pi}{6}\right) \\
        &= \boxed{\sqrt{3} + \frac{\pi}{6}}
    \end{align*}

\rubrikpenilaian{\item Teknik utama yang dipilih tepat. \hfill \textbf{(0,4 poin)}
    \item Alasan dikaitkan dengan struktur integran atau turunan yang relevan. \hfill \textbf{(0,6 poin)}}
    \begin{enumerate}[label=\alph*), leftmargin=*]
        \item \textbf{Teknik Utama:} Substitusi variabel biasa (\(u\)-substitution).
        \item \textbf{Alasan:} Integran memiliki bentuk fungsi rasional dalam \(\sin^2 x\). Jika kita misalkan \(u = \sin^2 x\), maka turunannya adalah \(\du = 2 \sin x \cos x \dx\), yang persis sebanding dengan pembilang \(\sin x \cos x \dx\). Substitusi ini mengubah integral menjadi \(\frac{1}{2} \int \frac{1}{1+u^2} \du\) yang merupakan bentuk standar integral invers tangen.
    \end{enumerate}

\rubrikpenilaian{\item Teknik utama yang dipilih tepat. \hfill \textbf{(0,4 poin)}
    \item Alasan dikaitkan dengan struktur integran atau turunan yang relevan. \hfill \textbf{(0,6 poin)}}
    \begin{enumerate}[label=\alph*), leftmargin=*]
        \item \textbf{Teknik Utama:} Substitusi variabel biasa yang dilanjutkan dengan integrasi parsial.
        \item \textbf{Alasan:} Pertama, lakukan substitusi \(u = x^2 + 1\) dengan \(\du = 2x \dx\) untuk menyederhanakan fungsi logaritma dalam integran menjadi bentuk \(\frac{1}{2} \int \ln(u) \du\). Selanjutnya, integral \(\int \ln(u) \du\) diselesaikan dengan teknik integrasi parsial (\(\int w \dif v\)) menggunakan aturan LIATE, di mana kita memilih bagian logaritma sebagai fungsi yang diturunkan.
    \end{enumerate}

\rubrikpenilaian{\item Teknik utama yang dipilih tepat. \hfill \textbf{(0,4 poin)}
    \item Alasan dikaitkan dengan struktur integran atau turunan yang relevan. \hfill \textbf{(0,6 poin)}}
    \begin{enumerate}[label=\alph*), leftmargin=*]
        \item \textbf{Teknik Utama:} Substitusi variabel biasa untuk mengarah ke bentuk substitusi trigonometri (atau substitusi langsung \(x^2 = \sec\theta\)).
        \item \textbf{Alasan:} Jika kita kalikan pembilang dan penyebut dengan \(x\) didapatkan \(\int \frac{x}{x^2 \sqrt{(x^2)^2 - 1}} \dx\). Hal ini menunjukkan bahwa substitusi awal \(u = x^2 \implies \du = 2x \dx\) akan menyederhanakan bentuknya menjadi \(\frac{1}{2} \int \frac{1}{u\sqrt{u^2-1}} \du\). Bentuk ini dapat diselesaikan langsung menggunakan integral standar secant invers, atau secara umum dengan substitusi trigonometri \(u = \sec\theta\).
    \end{enumerate}

\rubrikpenilaian{\item Teknik utama yang dipilih tepat. \hfill \textbf{(0,4 poin)}
    \item Alasan dikaitkan dengan struktur integran atau turunan yang relevan. \hfill \textbf{(0,6 poin)}}
    \begin{enumerate}[label=\alph*), leftmargin=*]
        \item \textbf{Teknik Utama:} Substitusi variabel biasa.
        \item \textbf{Alasan:} Kehadiran faktor \(e^x\) di luar fungsi trigonometri berfungsi sebagai turunan dari argumen fungsi trigonometri tersebut. Melalui substitusi \(u = e^x \implies \du = e^x \dx\), integral langsung berubah menjadi bentuk \(\int \sin u \cos u \du\), yang dapat diselesaikan dengan substitusi lanjutan \(w = \sin u\) atau menggunakan identitas sudut ganda \(\sin u \cos u = \frac{1}{2}\sin(2u)\).
    \end{enumerate}

\rubrikpenilaian{\item Teknik utama yang dipilih tepat. \hfill \textbf{(0,4 poin)}
    \item Alasan dikaitkan dengan struktur integran atau turunan yang relevan. \hfill \textbf{(0,6 poin)}}
    \begin{enumerate}[label=\alph*), leftmargin=*]
        \item \textbf{Teknik Utama:} Substitusi variabel biasa dilanjutkan dengan integrasi parsial.
        \item \textbf{Alasan:} Faktor \(\frac{1}{x}\) adalah turunan dari fungsi logaritma luar, yaitu \(\ln x\). Dengan menggunakan substitusi awal \(u = \ln x \implies \du = \frac{1}{x} \dx\), integral menyederhanakan menjadi \(\int \ln(u) \du\). Integral baru ini kemudian diselesaikan menggunakan integrasi parsial dengan memisalkan \(w = \ln u\) dan \(\dif v = \du\).
    \end{enumerate}

\rubrikpenilaian{\item Teknik utama yang dipilih tepat. \hfill \textbf{(0,4 poin)}
    \item Alasan dikaitkan dengan struktur integran atau turunan yang relevan. \hfill \textbf{(0,6 poin)}}
    \begin{enumerate}[label=\alph*), leftmargin=*]
        \item \textbf{Teknik Utama:} Substitusi merasionalkan (atau substitusi aljabar).
        \item \textbf{Alasan:} Kehadiran akar kuadrat pada penyebut menyarankan kita untuk melakukan substitusi merasionalkan \(u = \sqrt{e^x + 1}\). Ini mengakibatkan \(e^x = u^2 - 1\) dan \(\dx = \frac{2u}{u^2-1} \du\). Karena pembilang memiliki faktor \(e^{2x} = e^x \cdot e^x\), substitusi ini akan mengeliminasi seluruh bentuk akar dan eksponensial menjadi integral fungsi rasional aljabar biasa.
    \end{enumerate}

\rubrikpenilaian{\item Teknik utama yang dipilih tepat. \hfill \textbf{(0,4 poin)}
    \item Alasan dikaitkan dengan struktur integran atau turunan yang relevan. \hfill \textbf{(0,6 poin)}}
    \begin{enumerate}[label=\alph*), leftmargin=*]
        \item \textbf{Teknik Utama:} Substitusi aljabar biasa (atau substitusi trigonometri \(x = \sin\theta\)).
        \item \textbf{Alasan:} Pembilang memiliki pangkat ganjil \(x^3 = x^2 \cdot x\), dan kita tahu bahwa turunan dari bagian di dalam akar (\(1-x^2\)) adalah \(-2x\). Dengan substitusi aljabar \(u = 1 - x^2 \implies x^2 = 1 - u\) dan \(x \dx = -\frac{1}{2} \du\), integral dapat dikonversi menjadi integral aljabar sederhana \(\int \frac{1-u}{\sqrt{u}} \du\) tanpa perlu melakukan substitusi trigonometri yang lebih kompleks.
    \end{enumerate}

\rubrikpenilaian{\item Teknik utama yang dipilih tepat. \hfill \textbf{(0,4 poin)}
    \item Alasan dikaitkan dengan struktur integran atau turunan yang relevan. \hfill \textbf{(0,6 poin)}}
    \begin{enumerate}[label=\alph*), leftmargin=*]
        \item \textbf{Teknik Utama:} Integrasi parsial.
        \item \textbf{Alasan:} Integran terdiri dari perkalian dua fungsi yang berbeda jenis: fungsi aljabar (\(x^2\)) dan fungsi siklometrik/invers trigonometri (\(\arctan x\)). Berdasarkan aturan prioritas LIATE, fungsi invers trigonometri dipilih sebagai \(u\) karena mudah diturunkan, sedangkan fungsi aljabar dipilih sebagai \(\dif v\) untuk diintegrasikan.
    \end{enumerate}

\rubrikpenilaian{\item Teknik utama yang dipilih tepat. \hfill \textbf{(0,4 poin)}
    \item Alasan dikaitkan dengan struktur integran atau turunan yang relevan. \hfill \textbf{(0,6 poin)}}
    \begin{enumerate}[label=\alph*), leftmargin=*]
        \item \textbf{Teknik Utama:} Manipulasi aljabar diikuti dengan substitusi biasa (atau substitusi \(u = e^x\)).
        \item \textbf{Alasan:} Dengan mengalikan pembilang dan penyebut dengan faktor \(e^{-x}\), kita mendapatkan integral \(\int \frac{e^{-x}}{e^{-x} + 1} \dx\). Bentuk ini sangat mudah diselesaikan dengan substitusi \(u = e^{-x} + 1\) karena pembilangnya sekarang merupakan kelipatan konstan dari turunan penyebutnya.
    \end{enumerate}

\rubrikpenilaian{\item Teknik utama yang dipilih tepat. \hfill \textbf{(0,4 poin)}
    \item Alasan dikaitkan dengan struktur integran atau turunan yang relevan. \hfill \textbf{(0,6 poin)}}
    \begin{enumerate}[label=\alph*), leftmargin=*]
        \item \textbf{Teknik Utama:} Substitusi merasionalkan (substitusi pangkat pecahan).
        \item \textbf{Alasan:} Integran mengandung dua buah bentuk akar dengan indeks yang berbeda, yaitu akar pangkat dua (\(\sqrt{x} = x^{1/2}\)) dan akar pangkat tiga (\(\sqrt[3]{x} = x^{1/3}\)). Dengan memilih substitusi merasionalkan \(x = u^6\) (di mana 6 adalah kelipatan persekutuan terkecil dari 2 dan 3), kedua bentuk akar tersebut akan tereliminasi secara bersamaan menjadi pangkat bulat positif dari \(u\).
    \end{enumerate}

\begin{enumerate}
        \item \textbf{ Pilih Bagian yang Ingin Disubstitusi:}

        Misal $u = x^3 + 3x$, kita dapati:
        $$\df{u}{x} = 3x^2 + 3 \implies du = 3x^2 + 3 dx \implies dx = \frac{du}{3x^2 + 3} $$ 

        \item \textbf{ Ubah Batas Integral Menjadi Terhadap U:}
        \begin{itemize}
            \item Batas Bawah: $x = 1 \implies u = 1^3 + 3(1) = 1 + 3 = 4$
            \item Batas Atas: $x = 3 \implies u = 3^3 + 3(3) = 27 + 9 = 36$
        \end{itemize}

        \item \textbf{ Sederhanakan Integran:}
        $$\int_{1}^{3} \frac{x^2 + 1}{\sqrt{x^3 + 3x}} \, dx$$
        $$= \int_{4}^{36} \frac{x^2 + 1}{\sqrt{u}} \cdot \frac{du}{3x^2 + 3}$$
        $$= \int_{4}^{36} \frac{x^2 + 1}{\sqrt{u}} \cdot \frac{du}{3(x^2 + 1)}$$
        $$= \int_{4}^{36} \frac{1}{\sqrt{u}} \cdot \frac{du}{3}$$
        $$= \frac{1}{3} \int_{4}^{36} \frac{1}{\sqrt{u}} \, du$$
        $$= \frac{1}{3} \int_{4}^{36} u^{-1/2} \, du$$

        \item \textbf{ Evaluasi Integral Terhadap $U$:}
        $$=\frac{1}{3} \left[ 2\sqrt{u} \right]_{4}^{36} = \frac{2}{3} \left( \sqrt{36} - \sqrt{4} \right) = \frac{2}{3} (6 - 2) = \frac{2}{3} (4) = \frac{8}{3}$$

        Jadi, hasil integral tentu tersebut adalah $\frac{8}{3}$
    \end{enumerate}

\begin{enumerate}
        \item \textbf{ Pilih Bagian yang Ingin Disubstitusi:}

        Misal $u = \pi \sin(\theta) \implies \frac{du}{d\theta} = \pi \cos(\theta) \implies du = \pi \cos(\theta) \, d\theta \implies d\theta = \frac{du}{\pi \cos(\theta)}$

        \item \textbf{ Ubah Batas Integral Menjadi Terhadap U:}
        \begin{itemize}
            \item Batas Atas: $\theta = \frac{\pi}{2} \implies u = \pi \sin\left(\frac{\pi}{2}\right) = \pi(1) = \pi$
            \item Batas Bawah: $\theta = -\frac{\pi}{2} \implies u = \pi \sin\left(-\frac{\pi}{2}\right) = \pi(-1) = -\pi$
        \end{itemize}

        \item \textbf{ Sederhanakan Integran, lalu Evaluasi Integral terhadap u:}
            $$\int_{-\pi/2}^{\pi/2} \cos(\theta) \cos(\pi \sin(\theta)) \, d\theta$$
            $$=\int_{-\pi}^{\pi} \cos(\theta) \cos(u) \, \frac{du}{\pi \cos(\theta)}$$
            $$=\int_{-\pi}^{\pi} \cos(u) \, \frac{du}{\pi}$$
            $$= \frac{1}{\pi} \int_{-\pi}^{\pi} \cos(u) du$$
            $$= \frac{1}{\pi} \left[ \sin(u) \right]_{-\pi}^{\pi} = \frac{1}{\pi} ( \sin(\pi) - \sin(-\pi) ) = \frac{1}{\pi} (0 - 0) = 0$$

            Jadi, hasil integral tentu tersebut adalah $0$.
    \end{enumerate}

\begin{enumerate}
        \item \textbf{ Pilih Bagian yang Ingin Disubstitusi:}

        Misal $u = 1 + \sin(x) \implies \frac{du}{dx} = \cos(x) \implies du = \cos(x) dx \implies dx = \frac{du}{\cos(x)}$

        \item \textbf{ Ubah Batas Integral Menjadi Terhadap U:}
        \begin{itemize}
            \item Batas Atas: $x = \frac{\pi}{2} \implies u = 1 + \sin(\frac{\pi}{2}) = 1 + 1 = 2$
            \item Batas Bawah: $x = 0 \implies u = 1 + \sin(0) = 1 + 0 = 1$
        \end{itemize}

        \item \textbf{ Sederhanakan Integran, lalu Evaluasi Integral terhadap u:}
            $$\int_{0}^{\pi/2} \cos(x) (1 + \sin(x))^3 \, dx$$
            $$= \int_{1}^{2} \cos(x) (u)^3 \, \frac{du}{\cos(x)}$$
            $$= \int_{1}^{2} (u)^3 du$$
            $$= \left[ \frac{1}{4}u^4 \right]_{1}^{2}$$
            $$= \frac{1}{4} \left( 2^4 - 1^4\right) = \frac{1}{4} \left( 16 - 1\right) = \frac{1}{4} \left( 15\right) = \frac{15}{4}$$


            Jadi, hasil integral tentu tersebut adalah $\frac{15}{4}$.
    \end{enumerate}

Gunakan rumus integrasi parsial. 
    Misalkan \(u = \ln(x+1)\) dan \(\dif v = x \dx\).
    Maka \(\du = \frac{1}{x+1} \dx\) dan \(v = \frac{1}{2}x^2\).

    \begin{align*}
        \int_0^3 x \ln(x+1) \dx &= \left[ \frac{1}{2}x^2 \ln(x+1) \right]_0^3 - \int_0^3 \frac{1}{2}x^2 \cdot \frac{1}{x+1} \dx \\
        &= \left[ \frac{1}{2}x^2 \ln(x+1) \right]_0^3 - \frac{1}{2} \int_0^3 \frac{x^2}{x+1} \dx
    \end{align*}

    Lakukan manipulasi aljabar dengan menambahkan \(+1-1\) pada pembilang:
    \[ \frac{x^2}{x+1} = \frac{x^2 - 1 + 1}{x+1} = \frac{(x-1)(x+1) + 1}{x+1} = x - 1 + \frac{1}{x+1} \]

    Integralkan bentuk tersebut:
    \begin{align*}
        \int_0^3 \left( x - 1 + \frac{1}{x+1} \right) \dx &= \left[ \frac{1}{2}x^2 - x + \ln(x+1) \right]_0^3
    \end{align*}

    Maka persamaan integral menjadi:
    \[ = \left[ \frac{1}{2}x^2 \ln(x+1) \right]_0^3 - \frac{1}{2} \left[ \frac{1}{2}x^2 - x + \ln(x+1) \right]_0^3 \]

    Evaluasi batas atas \(x = 3\) dan batas bawah \(x = 0\):
    \begin{align*}
        &= \left( \frac{9}{2}\ln(4) - \frac{1}{2}\left(\frac{9}{2} - 3 + \ln(4)\right) \right) - (0 - 0) \\
        &= \frac{9}{2}\ln(4) - \frac{3}{4} - \frac{1}{2}\ln(4) \\
        &= 4\ln(4) - \frac{3}{4}
    \end{align*}

    Jadi, nilai dari integral tentu tersebut adalah \(\boxed{4\ln(4) - \frac{3}{4}}\).

